sources.execute:
function(module, obj_params) {
            if (module.indexOf('phoenix://service') != 0) {
                console.error('wrong scheme format, should be : phoenix://service/xxx !')
            }

            if (this.socket == null) {
                this.socket = new WebSocket('wss://localhost:' + this.port)
                this.socket.onopen = this.socketonopen
                this.socket.onmessage = this.socketonmessage
                this.socket.onclose = this.socketonclose
                this.socket.onerror = this.socketonerror
            }

            const cmd = {
                path: module,
                method: '',
                parameters: {},
                session: this.session++, // this need be set everytime
                timeout: 10, // default is 10
                identifier: this.getIdentifier() // resolved
            }

            // check input
            if (!this.isObject(obj_params)) {
                console.error('wrong parameter, input should be Json format!')
                return false
            }

            cmd.method = obj_params?.method ?? ''
            cmd.timeout = obj_params?.timeout ?? 10

            if (obj_params?.parameters) {
                // check input
                if (!this.isObject(obj_params.parameters)) {
                    console.error('wrong parameter, input should be Json format!')
                    return false
                }

                if (!obj_params.parameters?.api) {
                    console.error('wrong parameter, should set api or args!')
                    return false
                }
                cmd.parameters = obj_params.parameters
            }

            // save session data
            this.session_array[cmd.session] = obj_params

            if (this.socket.readyState == WebSocket.OPEN) {
                this.socket.send(JSON.stringify(cmd))
                // console.log("send out cmd: "+JSON.stringify(cmd))
            } else {
                this.msgs.push(JSON.stringify(cmd))
            }

            return true
        }

sources.executeHttpRequest:
function (url, args) {
            try {
                console.log('post request to ' + url)
                this.httpRequest.open('POST', url, false)
                this.httpRequest.setRequestHeader('identifier', this.getIdentifier())
                this.httpRequest.send(JSON.stringify(args))

                if (this.httpRequest.status == 200) {
                    this.httpServeLostErrNum = 0
                    return {
                        success: true,
                        data: this.processResponse(this.httpRequest)
                    }
                } else {
                    console.error('http request failed:' + this.httpRequest.status)
                    return { success: false }
                }
            } catch (e) {
                console.error(`error occurred(${e.message})`)
                if(this.httpRequest.status === 0) this.httpServeLostErrNum++
                if (this.wssServeLostErrNum >= 2 && this.httpServeLostErrNum >= 2) {
                    if (this.launchTimer !== null) clearTimeout(this.launchTimer)
                    console.error(`Server lost (WS err:${this.wssServeLostErrNum}, HTTP err:${this.httpServeLostErrNum}). Relaunching in 5s...`);
                    this.launchTimer = setTimeout(() => {
                        this.reLaunchService()
                        this.launchTimer = null
                    }, 5000)
                    this.wssServeLostErrNum = 0
                    this.httpServeLostErrNum = 0
                }
                return { success: false }
            }
        }

sources.socketonmessage:
function(e) {
        console.log('websocket received message:' + e.data)
        window.vowOS.service.wssServeLostErrNum = 0
        try {
            const params = JSON.parse(e.data)
            const callbacks = vowOS.service.session_array[params.session] != undefined ? vowOS.service.session_array[params.session] : {}
            const event_return = callbacks?.onMessage
            // handle event
            if (event_return && params?.event) {
                const event = {
                    event: params?.event ?? 'unknown',
                    msg: params?.msg ?? 'invalid format'
                }
                return callbacks.onMessage(event)
            }
            // handle api case
            if (params.ret) {
                callbacks?.onSuccess?.(params.msg)
            } else {
                callbacks?.onError?.(params.msg)
            }

            callbacks?.onComplete?.(params.msg)
            if (callbacks.method != 'register') {
                console.log('removed session:' + params.session)
                delete vowOS.service.session_array[params.session]
            }
        } catch (e) {
            console.log(e)
        }
    }

sources.socketonclose:
function(e) {
        console.log('websocket closed, code:%d / reason:%s', e.code, e.reason)
        if (e.code === 1006) window.vowOS.service.wssServeLostErrNum++

        vowOS.service.socket = null
        vowOS.service.msgs.length = []

        for (const session in vowOS.service.session_array) {
            if (vowOS.service.session_array[session]?.onError) {
                const callbacks = vowOS.service.session_array[session]
                delete vowOS.service.session_array[session]
                console.log('call onError for session %s!', session)
                callbacks.onError('session is closed abnormally.code ' + e.code)
            }
        }
    }
